  "steps": [
    {
      "id": "1",
      "label": "Haemostasis: Blood vessels constrict and platelets form a clot that stops bleeding."
    },
    {
      "id": "2",
      "label": "Inflammation: Neutrophils and then macrophages enter the wound and clear bacteria and debris."
    },
    {
      "id": "3",
      "label": "Proliferation: Fibroblasts lay down granulation tissue, new blood vessels form, and the wound edges contract."
    },
    {
      "id": "4",
      "label": "Remodelling: Collagen is reorganised and the scar gains strength, although it never regains the full strength of unwounded skin (can last a year or more)."
    }
  ],
